window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e5cc6036482e584e"]={"versions": [{"id": "FIG-e5cc6036482e584e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der AUTOSAR E2E-Protection-Wrapper-Funktion <code>E2EPW_Write2</code>. Das Diagramm modelliert das Zusammenspiel zwischen Anwendungsschicht (SWC), dem E2E-Wrapper, der AUTOSAR E2E-Library (Profilfunktion <code>E2E_PXXProtect</code>) und der AUTOSAR-Laufzeitumgebung (RTE, Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsparameter:</strong> <code>AppDataEl</code> (Zeiger auf das zu übertragende Anwendungsdatenelement).</li>\n<li><strong>Zustands- & Konfigurationsstrukturen:</strong> <code>Config2</code>, <code>State2</code>, Repräsentationspuffer <code>Data</code> (IPDU-Repräsentation).</li>\n<li><strong>Lokale Statusvariablen:</strong> <code>retRteWrite</code>, <code>retE2EProtect</code>, <code>plausibilityChecks</code> bzw. <code>plausibilitychecks</code>, <code>ret</code>.</li>\n<li><strong>Externe Schnittstellen / Funktionsaufrufe:</strong></li>\n<li><code>E2E_PXXProtect(Config2, State2, Data)</code> (Schutzfunktion der E2E-Library).</li>\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code> (Schreibfunktion der RTE für Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>).</li>\n<li><strong>Konstanten & Fehlercodes:</strong> <code>RTE_E_OK</code>, <code>E2E_E_OK</code>, <code>E2E_E_INPUTERR_NULL</code>, <code>E2EPW_E_REDUNDANCY</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start über Initialknoten mit Eingabe <code>(AppDataEl)</code>. Initialisierung von <code>retRteWrite = RTE_E_OK</code>, <code>retE2EProtect = E2E_E_OK</code> und <code>plausibilityChecks = E2E_E_OK</code>.</li>\n<li><strong>Nullzeiger-Prüfung:</strong> Verzweigung an <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, anschließender Übergang direkt zum finalen Zusammenführungsknoten.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die IPDU-Repräsentation <code>Data</code>, sofern es sich um ein komplexes Datenelement handelt; andernfalls Kopieren als Byte-Array nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Schutzberechnung:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config2, State2, Data)</code>.</li>\n<li><strong>Schutzstatus-Prüfung:</strong> Verzweigung an <code>retE2EProtect == E2E_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Umgehung der RTE-Schreiboperation und Verzweigung direkt zum Zusammenführungsknoten vor der Rückgabewertbildung.</li>\n<li><code>[TRUE]</code>: Plausibilitätsprüfung, ob CRC- und Counter-Werte im serialisierten Puffer <code>Data</code> mit den Werten im Datenelement übereinstimmen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plausibilitätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Zuweisung <code>plausibilitychecks = E2EPW_E_REDUNDANCY</code>, keine Datenübertragung an die RTE.</li>\n<li><code>[TRUE]</code>: Ausführung des RTE-Schreibaufrufs <code>retRteWrite = Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisaggregation & Rückgabe:</strong> Zusammenführung aller Kontrollpfade. Bitweises Verknüpfen der Statuswerte zu <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>. Beenden über Aktivitätsendknoten mit <code>return ret</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Funktion kapselt die sicherheitsgerichtete Absicherung vor dem RTE-Versand; schlägt die E2E-Schutzberechnung oder der Redundanz-/Plausibilitätsabgleich fehl, wird die RTE-Schreibfunktion <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code> strikt nicht aufgerufen.</li>\n<li>Der aggregierte 32-Bit-Rückgabewert kodiert drei separate Statusebenen: Bits 0–7 für den RTE-Rückgabewert, Bits 8–15 für den E2E-Library-Status und Bits 16–23/31 für Wrapper-interne Plausibilitätsprüfungen (<code>E2E_E_INPUTERR_NULL</code>, <code>E2EPW_E_REDUNDANCY</code>).</li>\n<li>Bei komplexen Datenelementen ist zwingend eine typkonforme Serialisierung in ein lineares Byte-Array (<code>Data</code>) vorzusehen, bevor dieses der E2E-Bibliothek übergeben wird.</li>\n</ul>"}, {"id": "FIG-18f1c2cd5da0dcf5", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der AUTOSAR E2E-Protection-Wrapper-Funktion <code>E2EPW_Write2</code>. Das Diagramm modelliert das Zusammenspiel zwischen Anwendungsschicht (SWC), dem E2E-Wrapper, der AUTOSAR E2E-Library (Profilfunktion <code>E2E_PXXProtect</code>) und der AUTOSAR-Laufzeitumgebung (RTE, Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsparameter:</strong> <code>AppDataEl</code> (Zeiger auf das zu übertragende Anwendungsdatenelement).</li>\n<li><strong>Zustands- & Konfigurationsstrukturen:</strong> <code>Config2</code>, <code>State2</code>, Repräsentationspuffer <code>Data</code> (IPDU-Repräsentation).</li>\n<li><strong>Lokale Statusvariablen:</strong> <code>retRteWrite</code>, <code>retE2EProtect</code>, <code>plausibilityChecks</code> bzw. <code>plausibilitychecks</code>, <code>ret</code>.</li>\n<li><strong>Externe Schnittstellen / Funktionsaufrufe:</strong></li>\n<li><code>E2E_PXXProtect(Config2, State2, Data)</code> (Schutzfunktion der E2E-Library).</li>\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code> (Schreibfunktion der RTE für Port <code>&lt;p&gt;</code> und Datenelement <code>&lt;o&gt;</code>).</li>\n<li><strong>Konstanten & Fehlercodes:</strong> <code>RTE_E_OK</code>, <code>E2E_E_OK</code>, <code>E2E_E_INPUTERR_NULL</code>, <code>E2EPW_E_REDUNDANCY</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start über Initialknoten mit Eingabe <code>(AppDataEl)</code>. Initialisierung von <code>retRteWrite = RTE_E_OK</code>, <code>retE2EProtect = E2E_E_OK</code> und <code>plausibilityChecks = E2E_E_OK</code>.</li>\n<li><strong>Nullzeiger-Prüfung:</strong> Verzweigung an <code>AppDataEl == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Setzen von <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, anschließender Übergang direkt zum finalen Zusammenführungsknoten.</li>\n<li><code>[FALSE]</code>: Serialisierung von <code>AppDataEl</code> in die IPDU-Repräsentation <code>Data</code>, sofern es sich um ein komplexes Datenelement handelt; andernfalls Kopieren als Byte-Array nach <code>Data</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>E2E-Schutzberechnung:</strong> Aufruf von <code>retE2EProtect = E2E_PXXProtect(Config2, State2, Data)</code>.</li>\n<li><strong>Schutzstatus-Prüfung:</strong> Verzweigung an <code>retE2EProtect == E2E_E_OK</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Umgehung der RTE-Schreiboperation und Verzweigung direkt zum Zusammenführungsknoten vor der Rückgabewertbildung.</li>\n<li><code>[TRUE]</code>: Plausibilitätsprüfung, ob CRC- und Counter-Werte im serialisierten Puffer <code>Data</code> mit den Werten im Datenelement übereinstimmen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plausibilitätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[FALSE]</code>: Zuweisung <code>plausibilitychecks = E2EPW_E_REDUNDANCY</code>, keine Datenübertragung an die RTE.</li>\n<li><code>[TRUE]</code>: Ausführung des RTE-Schreibaufrufs <code>retRteWrite = Rte_Write_&lt;p&gt;_&lt;o&gt;(AppDataEl)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisaggregation & Rückgabe:</strong> Zusammenführung aller Kontrollpfade. Bitweises Verknüpfen der Statuswerte zu <code>ret = retRteWrite | (retE2EProtect &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16)</code>. Beenden über Aktivitätsendknoten mit <code>return ret</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Funktion kapselt die sicherheitsgerichtete Absicherung vor dem RTE-Versand; schlägt die E2E-Schutzberechnung oder der Redundanz-/Plausibilitätsabgleich fehl, wird die RTE-Schreibfunktion <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code> strikt nicht aufgerufen.</li>\n<li>Der aggregierte 32-Bit-Rückgabewert kodiert drei separate Statusebenen: Bits 0–7 für den RTE-Rückgabewert, Bits 8–15 für den E2E-Library-Status und Bits 16–23/31 für Wrapper-interne Plausibilitätsprüfungen (<code>E2E_E_INPUTERR_NULL</code>, <code>E2EPW_E_REDUNDANCY</code>).</li>\n<li>Bei komplexen Datenelementen ist zwingend eine typkonforme Serialisierung in ein lineares Byte-Array (<code>Data</code>) vorzusehen, bevor dieses der E2E-Bibliothek übergeben wird.</li>\n</ul>"}], "trans": [{"from": "FIG-e5cc6036482e584e", "to": "FIG-18f1c2cd5da0dcf5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
